#!/usr/bin/env node
/**
 * Replace the stock tsr "do NOT edit" banner in app/src/routeTree.gen.ts
 * with the hosted-edit contract. Hosted apps have no tsr binary; agents
 * there MUST hand-edit this file, so the seeded bytes cannot carry a
 * banner that forbids it. Runs as part of `generate-routes`; the drift
 * gate (`check:route-tree`) regenerates through that same script, so the
 * committed file always matches wrapper output, never raw tsr output.
 *
 * Fails hard if the stock banner is missing so a tsr format change
 * surfaces here instead of silently shipping the wrong banner.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const genPath = join(
  fileURLToPath(new URL("..", import.meta.url)),
  "app/src/routeTree.gen.ts"
);

const STOCK_BANNER = `// This file was automatically generated by TanStack Router.
// You should NOT make any changes in this file as it will be overwritten.
// Additionally, you should also exclude this file from your linter and/or formatter to prevent it from being checked or modified.`;

const HOSTED_BANNER = `// Generated by \`pnpm generate-routes\` (template-only; hosted apps have no
// generator). When you add, move, or delete a file under src/routes/, edit
// this file by hand to match: the import, the route const, all three
// FileRoutesBy* interfaces, the FileRoutesByPath module augmentation, and
// the children wiring at the bottom. A route missing from the children
// wiring 404s at runtime, so mirror an existing route end to end.`;

const source = readFileSync(genPath, "utf8");
if (!source.includes(STOCK_BANNER)) {
  console.error(
    "rewrite-route-tree-banner — stock tsr banner not found in routeTree.gen.ts; tsr output format changed, update this script."
  );
  process.exit(1);
}
writeFileSync(genPath, source.replace(STOCK_BANNER, HOSTED_BANNER));
